import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"代码架构说明","description":"完全依据源码重新整理的 19 篇架构说明，覆盖服务组装、任务调度、执行器、上下文、存储、前端与渠道接入。","frontmatter":{"title":"代码架构说明","description":"完全依据源码重新整理的 19 篇架构说明，覆盖服务组装、任务调度、执行器、上下文、存储、前端与渠道接入。","outline":[2,3]},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md","lastUpdated":1793797632000}'),h={name:"architecture/index.md"};function l(i,t,o,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="代码架构说明" tabindex="-1">代码架构说明 <a class="header-anchor" href="#代码架构说明" aria-label="Permalink to &quot;代码架构说明&quot;">​</a></h1><p class="lead">这一板块不看设计文档，只看代码。它回答的是「这套系统现在实际上是怎么被拼起来、怎么跑起来的」，而不是「当初打算怎么设计」。</p><h2 id="为什么单独有这个板块" tabindex="-1">为什么单独有这个板块 <a class="header-anchor" href="#为什么单独有这个板块" aria-label="Permalink to &quot;为什么单独有这个板块&quot;">​</a></h2><p>站上的<a href="/hearth-os/design/">设计说明</a>写的是产品定位、方案取舍和验收目标，属于方案视角；随着实现推进，其中部分事实已经与代码脱节。本板块在 2026-11-13 从 <code>apps/</code> 与 <code>packages/</code> 的源码逐文件重新整理，刻意不参考仓库内的既有设计文档，也不列举具体代码，只用自然语言描述结构、流程、状态与边界。</p><p>两者不是替代关系：想知道「为什么这样设计」读设计说明，想知道「代码里现在是什么」读本板块。遇到不一致时，以源码和本板块的描述为准。</p><h2 id="_19-篇怎么组织" tabindex="-1">19 篇怎么组织 <a class="header-anchor" href="#_19-篇怎么组织" aria-label="Permalink to &quot;19 篇怎么组织&quot;">​</a></h2><p>整套说明按五层归类，每篇只讲自己那一块，篇与篇之间用「本文边界」表格划清分工。</p><table tabindex="0"><thead><tr><th>层级</th><th>篇章</th><th>这一层管什么</th></tr></thead><tbody><tr><td>基座与运维</td><td><a href="./Hearth-领域契约与状态机设计说明.html">领域契约与状态机</a></td><td>全仓共享的类型、枚举、DTO 与默认值规则</td></tr><tr><td>基座与运维</td><td><a href="./Hearth-存储设计说明.html">事件溯源与存储管理</a></td><td>数据落在哪里、事件为真源、读视图与备份</td></tr><tr><td>基座与运维</td><td><a href="./定时任务设计说明.html">定时任务与后台周期</a></td><td>后台有哪些循环、各自的触发时机</td></tr><tr><td>基座与运维</td><td><a href="./Hearth-可观测性与首次引导设计说明.html">可观测性与首次引导</a></td><td>健康快照、诊断导出、首次运行检查</td></tr><tr><td>执行主干</td><td><a href="./Hearth-任务执行调度器设计说明.html">任务执行调度器</a></td><td>一次任务从排队到终态的全过程</td></tr><tr><td>执行主干</td><td><a href="./Hearth-模型接入与执行器适配设计说明.html">模型接入与执行器适配</a></td><td>模型协议客户端与七种执行器如何接进来</td></tr><tr><td>执行主干</td><td><a href="./Hearth-Agent运行时设计说明.html">Agent 运行时</a></td><td>单 Agent 的工具循环、内置工具与上下文压缩</td></tr><tr><td>执行主干</td><td><a href="./Hearth-工作区隔离与产物设计说明.html">工作区隔离与产物</a></td><td>工作区、git worktree、依赖环境与模板</td></tr><tr><td>执行主干</td><td><a href="./Hearth-MCP与任务委派设计说明.html">MCP 与任务委派</a></td><td>外部工具接入、子代理、委派与交接</td></tr><tr><td>执行主干</td><td><a href="./意图识别路由与执行器自动选择.html">意图识别与执行器选择</a></td><td>从一句话意图到选定执行器的路由</td></tr><tr><td>认知与知识</td><td><a href="./hearth-os-上下文管理设计.html">上下文管理</a></td><td>上下文账本、编译、投影与诊断</td></tr><tr><td>认知与知识</td><td><a href="./Hearth-知识本体与指代消解设计说明.html">知识本体与指代消解</a></td><td>实体、关系、决定与指代的解析</td></tr><tr><td>认知与知识</td><td><a href="./Hearth-自进化机制设计说明.html">技能与方法资产</a></td><td>经验如何沉淀成可复用的方法</td></tr><tr><td>认知与知识</td><td><a href="./Hearth-数据源与联网设计说明.html">数据源与联网</a></td><td>来源采集、网页抓取、搜索与 GitHub 集成</td></tr><tr><td>接入与治理</td><td><a href="./Hearth-服务组装与API接入设计说明.html">服务组装与 API 接入</a></td><td>一个进程的启动链、安全边界与事件流</td></tr><tr><td>接入与治理</td><td><a href="./判定审批机制说明.html">判定、审批与安全</a></td><td>完成判定、人工审批与外部副作用</td></tr><tr><td>接入与治理</td><td><a href="./Hearth-主动式引擎设计说明.html">主动式引擎与注意力</a></td><td>主动建议、常驻意图、入站分拣与看门狗</td></tr><tr><td>交互与触达</td><td><a href="./Hearth-前端架构设计说明.html">前端设计与实时事件桥</a></td><td>前端分层、状态管理与事件消费</td></tr><tr><td>交互与触达</td><td><a href="./Hearth-渠道与设备接入设计说明.html">渠道与设备接入</a></td><td>飞书、邮件、设备配对与离线回放</td></tr></tbody></table><h2 id="建议的阅读顺序" tabindex="-1">建议的阅读顺序 <a class="header-anchor" href="#建议的阅读顺序" aria-label="Permalink to &quot;建议的阅读顺序&quot;">​</a></h2><ul><li><strong>先建立全貌</strong>：服务组装与 API 接入 → 领域契约与状态机 → 事件溯源与存储管理，这三者决定后面所有模块的形状。</li><li><strong>再看主线</strong>：任务执行调度器 → 模型接入与执行器适配 → Agent 运行时 → 工作区隔离与产物，跟完一次任务的执行路径。</li><li><strong>按需深入</strong>：其余篇章可单独阅读；每篇开头的「本文边界」表格会指出前置知识在哪一篇。</li></ul><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>每篇开头的边界表格写明「哪些内容已被哪篇讲过」，因此本板块内部不重复展开同一机制；跨篇引用都做成了可点击链接。</li><li>括号里出现的文件名只用于定位核对，不是代码片段；全文不列举具体实现代码。</li><li>状态名、常量数值、默认值与目录名均以整理时的源码为准，代码变更后需重新核对。</li><li>整理范围主要是服务端源码、共享包与前端源码；评测控制台只保留构建产物，未在代码中展开。</li></ul><p>整理日期：2026-11-13。</p>',13)])])}const p=d(h,[["render",l]]);export{m as __pageData,p as default};
